/**
 * HTML report renderer (Plan v0.2 item). Deterministic, self-contained
 * (inline CSS, no external assets), bilingual labels matching the terminal output.
 */
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const SEV_COLOR = {
    critical: "#b91c1c", high: "#c2410c", medium: "#a16207", low: "#4d7c0f", info: "#475569",
};
export function renderHtml(result) {
    const s = result.summary;
    const rows = [...result.findings]
        .filter((f) => f.suppression === null)
        .map((f) => `<tr>
<td><span class="chip" style="background:${SEV_COLOR[f.severity]}">${f.severity}</span></td>
<td><code>${esc(f.id)}</code>${f.needs_confirmation ? ' <span class="confirm">needs confirmation</span>' : ""}</td>
<td>${esc(f.title)}</td>
<td><code>${esc(f.file)}:${f.line}</code></td>
<td class="ev">${esc(f.evidence.masked)}</td>
</tr>`)
        .join("\n");
    const covered = result.coverage.classes_covered.map((c) => `<li>${esc(c)}</li>`).join("\n");
    const notCovered = result.coverage.classes_not_covered.map((c) => `<li>${esc(c)}</li>`).join("\n");
    return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Anubis Guardian — ${esc(result.target.path)} — ${result.score}/100</title>
<style>
  :root { color-scheme: light; }
  body { font-family: ui-sans-serif, system-ui, "Segoe UI", Tahoma, sans-serif; margin: 0; background: #f8fafc; color: #0f172a; }
  header { background: #0f172a; color: #f8fafc; padding: 28px 32px; }
  header h1 { margin: 0 0 6px; font-size: 22px; }
  .muted { color: #94a3b8; font-size: 13px; }
  .score { font-size: 44px; font-weight: 800; margin: 10px 0 2px; }
  .chips span { display: inline-block; margin-right: 8px; padding: 2px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; color: #fff; }
  main { padding: 24px 32px; max-width: 1100px; margin: 0 auto; }
  table { border-collapse: collapse; width: 100%; background: #fff; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden; }
  th, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid #e2e8f0; font-size: 13px; vertical-align: top; }
  th { background: #f1f5f9; font-size: 12px; text-transform: uppercase; letter-spacing: .04em; }
  code { font-family: ui-monospace, "JetBrains Mono", monospace; font-size: 12px; }
  .chip { color: #fff; padding: 2px 10px; border-radius: 999px; font-size: 11px; font-weight: 700; text-transform: uppercase; }
  .confirm { background: #fef3c7; color: #92400e; padding: 1px 8px; border-radius: 999px; font-size: 11px; }
  .ev { max-width: 320px; overflow-wrap: anywhere; }
  h2 { font-size: 16px; margin: 28px 0 10px; }
  ul { columns: 2; font-size: 13px; }
  footer { padding: 20px 32px; color: #64748b; font-size: 12px; }
</style>
</head>
<body>
<header>
  <h1>Anubis Guardian — Security Report</h1>
  <div class="muted">${esc(result.target.path)} · v${result.version} · advisory snapshot ${esc(result.advisory_snapshot)} · deterministic · no-exec</div>
  <div class="score">${result.score}<span style="font-size:18px;color:#94a3b8">/100 (${result.grade})</span></div>
  <div class="chips">
    <span style="background:#b91c1c">C:${s.critical}</span><span style="background:#c2410c">H:${s.high}</span><span style="background:#a16207">M:${s.medium}</span><span style="background:#4d7c0f">L:${s.low}</span><span style="background:#475569">I:${s.info}</span>
  </div>
</header>
<main>
  <h2>Findings (${s.critical + s.high + s.medium + s.low + s.info} open)</h2>
  <table>
    <tr><th>Severity</th><th>Rule</th><th>Title</th><th>Location</th><th>Evidence (masked)</th></tr>
    ${rows || '<tr><td colspan="5">No open findings — score 100/A.</td></tr>'}
  </table>
  <h2>Coverage — classes covered</h2>
  <ul>${covered}</ul>
  <h2>Coverage — classes NOT covered (honesty contract)</h2>
  <ul>${notCovered}</ul>
</main>
<footer>Generated by anubis-guardian (deterministic renderers — same findings.json always produces this exact HTML). Masking: first-4 + sha256 prefix only.</footer>
</body>
</html>
`;
}
